-- Change 'l0004_recap_rows': R02 recap as rows: Lao, sounds like, cue
-- Generated by approved-scripts/db_sql.py change from data/*.csv. Upserts change only rows that differ,
-- including rows lessons use. Rows: 1 rules.
-- IDs: rules:R02

insert into public.rules as t (rule_id, name_en, teach_en, intro_lesson_id, source, confidence, notes) values
  ('R02', 'One shape, three vowels', 'The stroke າ is part of three different vowels. Look at what is written before and above the consonant to tell them apart. || ◌າ | aa | the a in ''father'' || ເ◌ົາ | ao | the ow in ''now'' || ◌ຳ | am | the um in ''hum''', 'L0004', 'SRC-AGENT:lesson', 'unverified', 'Recap card, not a pronunciation rule (owner 2026-11-09, LESSON_PLAN decision 18): the same stroke appears in V03, V35 and V36, which looks like a contradiction unless it is pointed out. Format: prose, then rows separated by '' || '', each row ''Lao | sounds like | cue'' (the app shows them as a table). Sounds are the respellings of V03, V35, V36 (vowels are the same in both transliteration styles); cues repeat the units'' teach texts. Wording by agent. R01 is reserved for dead syllables.')
on conflict (rule_id) do update set name_en = excluded.name_en, teach_en = excluded.teach_en, intro_lesson_id = excluded.intro_lesson_id, source = excluded.source, confidence = excluded.confidence, notes = excluded.notes, retired_at = null
where (t.retired_at is not null or (t.name_en, t.teach_en, t.intro_lesson_id, t.source, t.confidence, t.notes) is distinct from (excluded.name_en, excluded.teach_en, excluded.intro_lesson_id, excluded.source, excluded.confidence, excluded.notes));
